INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_civil_lease','民法典租赁合同编简化资料','民法典租赁','全国人大','2021-01-01','现行有效','租赁合同、锁房款退还、维修和违约责任的常识性资料。');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_privacy','个人信息保护常识资料','个人信息','全国人大','2021-11-01','现行有效','身份证、收入证明等个人信息最小披露原则。');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_lease_deposit','stat_civil_lease','租赁-锁房款退还',1,'锁房款退还与费用','锁房款退还、服务费、维修责任宜书面列明，不宜仅凭口头承诺。');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_lease_repair','stat_civil_lease','租赁-维修',2,'维修责任','房屋设施、租赁证明材料、合同/设施资料和公共区域维修责任宜在合同中列明。');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_privacy_min','stat_privacy','个人信息-最小必要',1,'最小披露','身份证、收入证明等敏感材料应在必要、授权、最小范围内处理。');
